assert int((T70 & keep_wA).sum()) == 70  # all kept on wA

# eAll edge set (l142 E_ARMS form): drop all 93 incident edges on the wA set
e_drop_all = (src_all == GI) | (dst_all == GI)
emask_eA = emask_wA & ~e_drop_all
